DECK_CSS='''*{box-sizing:border-box}body{margin:0;background:#0d1410;font-family:Arial,Helvetica,sans-serif;color:#f4f6ed}.slide{position:relative;width:1280px;height:720px;padding:40px 48px 34px;background:#16221b;margin:20px auto;overflow:hidden}.kicker{font:12px monospace;letter-spacing:.15em;color:#d9ef65;margin:0 0 17px}h1{font:normal 45px/1.12 Georgia,serif;letter-spacing:-.025em;margin:0 0 18px;max-width:1160px}.statements{display:flex;gap:25px;margin:0 0 22px}.statements p{font-size:15px;line-height:1.4;margin:0;flex:1;border-top:1px solid #667258;padding-top:10px}.image-grid{display:grid;gap:16px;height:410px}.image-grid.n2{grid-template-columns:1fr 1fr}.image-grid.n3{grid-template-columns:1fr 1fr 1fr}.pic{margin:0;min-width:0;height:100%;display:flex;flex-direction:column;overflow:hidden}.pic img{width:100%;height:calc(100% - 44px);object-fit:contain;background:#f8faf4}.pic.photo img{object-fit:cover;background:none}.pic figcaption{font:10px/1.4 Arial,sans-serif;color:#ccd1c2;padding-top:8px;height:44px}.pic figcaption a{color:inherit}.foot{position:absolute;bottom:18px;left:48px;right:48px;border-top:1px solid #526046;padding-top:9px;display:flex;gap:12px;justify-content:space-between;font:10px/1.3 monospace;color:#b7c0aa}.foot .ref{max-width:860px}.cover{display:grid;grid-template-columns:1fr 1fr;gap:30px}.cover h1{font-size:74px;line-height:.98;margin:26px 0}.cover .cover-main{height:582px}.cover .cover-small{width:190px;height:180px;margin-top:26px}.cover p{font-size:20px;line-height:1.4;max-width:480px}.cover .cover-small figcaption{height:36px;font-size:9px}.source-list{display:grid;grid-template-columns:1fr 1fr;gap:13px 32px}.source-item{border-top:1px solid #526046;padding-top:8px;font-size:12px;line-height:1.35}.source-item a{color:#d9ef65;font-size:10px;display:block;overflow-wrap:anywhere;text-decoration:none;margin-top:3px}.credit-list{display:grid;grid-template-columns:1fr 1fr 1fr;gap:12px 22px}.credit-item{border-top:1px solid #526046;padding-top:7px;font-size:10px;line-height:1.4}.credit-item b{font-size:12px;display:block;margin-bottom:3px}.credit-item a{color:#d9ef65;text-decoration:none}.deck-nav{position:fixed;bottom:10px;right:20px;z-index:10;background:#d9ef65;color:#16221b;padding:5px 10px;font:12px monospace}.deck-nav button{border:0;background:transparent;cursor:pointer;padding:8px;font-size:15px}a{color:inherit}@media(max-width:1280px){.slide{transform-origin:top left;margin-left:0;margin-right:0}}@media print{@page{size:13.333333in 7.5in;margin:0}body{background:#16221b;-webkit-print-color-adjust:exact;print-color-adjust:exact}.slide{margin:0;width:1280px;height:720px;break-after:page;page-break-after:always}.slide:last-of-type{break-after:auto}.deck-nav{display:none}}
'''
def slidepic(a,extra=''):
 return f'<figure class="pic {"photo" if a in photos else "drawing"} {extra}"><img src="{data_image(a["path"],1800)}" alt="{h(a["title"])}"><figcaption>{a["id"]} / {h(a["title"])}<br>{h(a["author"])} · {image_year(a)} · {h(a["license"])} · <a href="{h(a["url"])}">Quelle</a></figcaption></figure>'
used=sorted(set(k for s in SLIDES for k in s['images']))
slide_html=[]
for s in SLIDES:
 title=h(s['title']).replace('\n','<br>');start=f'<section class="slide" id="slide-{s["number"]}" aria-label="Folie {s["number"]}">'
 foot=f'<footer class="foot"><span class="ref">Quellen: {h(s["refs"])}</span><span>Johannes Fink / {s["number"]:02d}</span></footer>'
 if s.get('layout')=='cover':
  content='<div class="cover"><div><div class="kicker">'+h(s['kicker'])+'</div><h1>'+title+'</h1><p>'+h(s['lines'][0])+'</p><div class="cover-small">'+slidepic(byid['P02'])+'</div></div><div class="cover-main">'+slidepic(byid['F01'])+'</div></div>'
 elif s.get('layout')=='sources':
  content=f'<p class="kicker">{s["kicker"]}</p><h1>{title}</h1><div class="source-list">'+''.join(f'<div class="source-item"><b>[{h(c)}] {h(t)}</b><a href="{h(u if u.startswith("https:") else "../"+u)}">{h(u.replace("https://", ""))}</a></div>' for c,t,u,d in SOURCES)+'</div>'
 elif s.get('layout') in ['credits','credits_plans']:
  credits=[]
  for key in used:
   a=byid[key]
   if s['layout']=='credits' and a not in photos:continue
   if s['layout']=='credits_plans' and a not in plans:continue
   credits.append(f'<div class="credit-item"><b>{key} / {h(a["title"])}</b>{h(a["author"])} · {image_year(a)}<br>{h(a["license"])} · <a href="{h(a["url"])}">Quellenseite ↗</a></div>')
  if s['layout']=='credits_plans':credits.append('<div class="credit-item"><b>A01–A05 / Eigene Analyseskizzen</b>Johannes Fink · CC BY 4.0<br>Ohne Maßstab, Quellen jeweils am Diagramm.</div>')
  content=f'<p class="kicker">{s["kicker"]}</p><h1>{title}</h1><div class="credit-list">'+''.join(credits)+'</div>'
 else:
  content=f'<p class="kicker">{s["kicker"]}</p><h1>{title}</h1><div class="statements">'+''.join('<p>'+h(t)+'</p>' for t in s['lines'])+'</div><div class="image-grid n'+str(len(s['images']))+'">'+''.join(slidepic(byid[k]) for k in s['images'])+'</div>'
 slide_html.append(start+content+foot+'</section>')
(OUT/'praesentation.html').write_text('<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="author" content="Johannes Fink"><title>Seattle Central Library — Präsentation</title><style>'+DECK_CSS+'</style></head><body>'+''.join(slide_html)+'<nav class="deck-nav"><button id="prev" aria-label="Vorige Folie">←</button><span id="slide-count">1 / 16</span><button id="next" aria-label="Nächste Folie">→</button></nav><script>let n=1;function go(d){n=Math.min(16,Math.max(1,n+d));document.getElementById("slide-"+n).scrollIntoView({behavior:"smooth"});document.getElementById("slide-count").textContent=n+" / 16"}document.getElementById("prev").onclick=()=>go(-1);document.getElementById("next").onclick=()=>go(1);document.addEventListener("keydown",e=>{if(["ArrowRight","PageDown"].includes(e.key)){e.preventDefault();go(1)}if(["ArrowLeft","PageUp"].includes(e.key)){e.preventDefault();go(-1)}});function scale(){if(innerWidth<1280){document.querySelectorAll(".slide").forEach(s=>{s.style.zoom=innerWidth/1280})}else document.querySelectorAll(".slide").forEach(s=>s.style.zoom="")}scale();addEventListener("resize",scale);</script></body></html>')
print('HTML complete:',len(assets),'assets;',len(SLIDES),'slides;',sum(s['seconds'] for s in SLIDES),'s;',sum(len(s['notes'].split()) for s in SLIDES if s['seconds']),'spoken words')
